# Enrich DISEASES with content from diseases_all_species.json
enrich_diseases(DISEASES, "Sugar Glider")


def analyze_symptoms(
    symptoms: List[str],
    age_stage: str = "",
    breed: str | None = None,
    *,
    onset: str | None = None,
    age_years: float | None = None,
    species: str | None = None,
    lab_values: dict | None = None,
    gender: str | None = None,
    vaccines=None,
    vaccination_status=None,
) -> Dict[str, Any]:
    """Run differential diagnosis for sugar gliders based on reported symptoms."""
    return analyze_symptoms_generic(
        symptoms,
        DISEASES,
        SYMPTOM_NAMES,
        ADVICE,
        onset=onset,
        age_years=age_years,
        breed=breed,
        species=species,
        lab_values=lab_values,
        gender=gender,
        vaccines=vaccines,
        vaccination_status=vaccination_status,
        prevalence_map=prevalence_data.SPECIES_PREVALENCE.get("sugar_glider", {}),
    )
